@@ -8,15 +8,20 @@ export function validarNit(nit) {
 }

 // RF-002: el IVA va incluido en el precio; se informa, no se suma.
-export function calcularFactura(items) {
+// RF-006: `descuentoGlobal` (porcentaje entero 0-100) se aplica sobre el total de las líneas, redondeado
+// con Math.round; el IVA y el neto se calculan sobre el total ya descontado.
+export function calcularFactura(items, { descuentoGlobal = 0 } = {}) {
   if (!Array.isArray(items) || items.length === 0) throw new Error("Una factura necesita al menos una línea");
-  let totalCentavos = 0;
+  if (!Number.isInteger(descuentoGlobal) || descuentoGlobal < 0 || descuentoGlobal > 100)
+    throw new RangeError("Descuento global inválido: debe ser un porcentaje entero de 0 a 100");
+  let subtotalCentavos = 0;
   for (const item of items) {
     if (!Number.isInteger(item.cantidad) || item.cantidad <= 0) throw new RangeError("Cantidad inválida");
     if (!Number.isInteger(item.precioUnitarioCentavos) || item.precioUnitarioCentavos < 0)
       throw new RangeError("Precio inválido: debe estar en centavos enteros");
-    totalCentavos += item.cantidad * item.precioUnitarioCentavos;
+    subtotalCentavos += item.cantidad * item.precioUnitarioCentavos;
   }
+  const totalCentavos = subtotalCentavos - Math.round((subtotalCentavos * descuentoGlobal) / 100);
   const ivaCentavos = Math.round(totalCentavos * TASA_IVA);
   return { totalCentavos, ivaCentavos, netoCentavos: totalCentavos - ivaCentavos };
 }
diff --git a/tests/factura.test.mjs b/tests/factura.test.mjs
index fabcb45..39e61e6 100644
--- a/tests/factura.test.mjs
+++ b/tests/factura.test.mjs
@@ -30,6 +30,57 @@ test("RF-003: una factura emitida no se puede modificar", () => {
   assert.throws(() => { "use strict"; f.totalCentavos = 1; }, TypeError);
 });

+const LINEAS_BASE = [
+  { cantidad: 2, precioUnitarioCentavos: 5000 },
+  { cantidad: 1, precioUnitarioCentavos: 1050 },
+];
+
+test("RF-006 T1: sin descuento global el resultado no cambia", () => {
+  const esperado = { totalCentavos: 11050, ivaCentavos: 1437, netoCentavos: 9613 };
+  assert.deepEqual(calcularFactura(LINEAS_BASE), esperado);
+  assert.deepEqual(calcularFactura(LINEAS_BASE, {}), esperado);
+  assert.deepEqual(calcularFactura(LINEAS_BASE, { descuentoGlobal: 0 }), esperado);
+});
+
+test("RF-006 T2: 10 % global; IVA y neto sobre el total descontado", () => {
+  assert.deepEqual(calcularFactura(LINEAS_BASE, { descuentoGlobal: 10 }), {
+    totalCentavos: 9945,
+    ivaCentavos: 1293,
+    netoCentavos: 8652,
+  });
+});
+
+test("RF-006 T3: el descuento se redondea al centavo con Math.round", () => {
+  assert.deepEqual(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 1005 }], { descuentoGlobal: 10 }), {
+    totalCentavos: 904,
+    ivaCentavos: 118,
+    netoCentavos: 786,
+  });
+});
+
+test("RF-006 T4: 100 % deja todo en cero", () => {
+  assert.deepEqual(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 5000 }], { descuentoGlobal: 100 }), {
+    totalCentavos: 0,
+    ivaCentavos: 0,
+    netoCentavos: 0,
+  });
+});
+
+test("RF-006 T5: descuento global inválido se rechaza con RangeError", () => {
+  for (const invalido of [101, -1, 10.5, "10", null, NaN]) {
+    assert.throws(() => calcularFactura(LINEAS_BASE, { descuentoGlobal: invalido }), RangeError, String(invalido));
+  }
+});
+
+test("RF-006 T6: validaciones existentes y emitirFactura no cambian", () => {
+  assert.throws(() => calcularFactura([], { descuentoGlobal: 10 }));
+  assert.throws(() => calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 10.5 }], { descuentoGlobal: 10 }), RangeError);
+  const f = emitirFactura({ numero: 8, nit: "1234567", razonSocial: "Cliente SA", items: LINEAS_BASE });
+  assert.equal(f.estado, "emitida");
+  assert.equal(f.totalCentavos, 11050);
+  assert.ok(Object.isFrozen(f));
+});
+
